r"""
Figure S13, panel a: per condition: occupancy map, and each animal's time near the stimulus.

Panel id figS13_a_cage_occupancy. Title: "Cage space".

Redrawn from the panel's data folder, data/figS13/figS13_a_cage_occupancy/
(DATA below), with numpy and matplotlib alone: what the panel shows is read
from that folder, and how the page lays it out -- the axes' rectangles in
page inches, limits, ticks, labels, titles, legends, colour maps, drawing
styles, and the decoration the data leave out (cage wireframes, category
outlines, category boundaries) -- is written below as literals, measured
off the published page.

Usage:

    python figS13_a_cage_occupancy.py [--data DIR] [--out-dir DIR]

writes figS13_a_cage_occupancy.pdf and figS13_a_cage_occupancy.png (400
dpi), the panel cut from its page, into supplemental_figures/figS13/ (OUT
below); figS13_page.py draws the whole page and code/render_all.py every
figure.
"""

